\coordinate (P) at (0,0);
\coordinate (R) at ({18*cos(40)},0);
\coordinate (Q) at (0,{-18*sin(40)});
\coordinate (S) at ({18*cos(40)-8},0);
\draw[black] (P)--(R)--(Q)--cycle (Q)--(S);
\draw[black,line width=0.4pt] ($(P)+(1.2,0)$)--($(P)+(1.2,-1.2)$)--($(P)+(0,-1.2)$);
\pic[draw=black,line width=0.4pt,angle radius=6mm,angle eccentricity=1.4,"$40^{\circ}$"] {angle=P--R--Q};
\pic[draw=black,line width=0.4pt,angle radius=5mm,angle eccentricity=1.4,"$\alpha$"] {angle=P--S--Q};
\draw[black,line width=0.4pt,{Stealth}-{Stealth}] ($(S)+(0,1)$)--node[above] {$8\text{ cm}$} ($(R)+(0,1)$);
\path (Q)--node[below right] {$18\text{ cm}$} (R);
\node[left] at (P) {$P$};
\node[below left] at (Q) {$Q$};
\node[above left] at (S) {$S$};
\node[right] at (R) {$R$};
